  </head>
  <body>
    <main id="app"></main>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        submitted: false,
      };

      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          placeholder: "Alex Morgan",
          required: true,
          autocomplete: "name",
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          placeholder: "alex@example.com",
          required: true,
          autocomplete: "email",
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          required: false,
          autocomplete: "tel",
          helperText: "Optional. Use a 10-digit phone number, such as (555) 123-4567.",
        },
      ];

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      function validate(values) {
        const errors = {};
        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const phonePattern = /^$|^(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;

        if (!values.fullName.trim()) {
          errors.fullName = "Enter your full name.";
        }

        if (!values.email.trim()) {
          errors.email = "Enter your email address.";
        } else if (!emailPattern.test(values.email.trim())) {
          errors.email = "Enter a valid email address, such as alex@example.com.";
        }

        if (values.phone.trim() && !phonePattern.test(values.phone.trim())) {
          errors.phone = "Enter a valid phone number, such as (555) 123-4567.";
        }

        return errors;
      }

      function FormField(field) {
        const error = state.errors[field.id];
        const errorId = `${field.id}-error`;
        const helperId = `${field.id}-helper`;
        const describedBy = [
          field.helperText ? helperId : "",
          error ? errorId : "",
        ]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required" aria-label="required">*</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              value="${escapeHtml(state.values[field.id])}"
              placeholder="${field.placeholder}"
              autocomplete="${field.autocomplete}"
              ${field.required ? "required" : ""}
              aria-invalid="${error ? "true" : "false"}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${
              field.helperText
                ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>`
                : ""
            }
            ${
              error
                ? `<p class="validation-message" id="${errorId}" role="alert">${error}</p>`
                : ""
            }
          </div>
        `;
      }

      function SupportContactForm() {
        const successMessage = state.submitted
          ? '<p class="success-message" role="status">Thanks. Your support request is ready to send.</p>'
          : "";

        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">Contact our team</h1>
            <p class="intro">
              Tell us how to reach you and a support specialist will follow up.
              Required fields are marked with an asterisk.
            </p>
            <form id="support-form" novalidate>
              ${fields.map(FormField).join("")}
              <button type="submit">Submit support request</button>
            </form>
            ${successMessage}
          </section>
        `;
      }

      function App() {
        return SupportContactForm();
      }

      function bindEvents() {
        document.querySelectorAll("input").forEach((input) => {
          input.addEventListener("input", (event) => {
            state.values[event.target.name] = event.target.value;
            state.errors = validate(state.values);
            state.submitted = false;
            render();
            document.getElementById(event.target.id).focus();
          });

          input.addEventListener("blur", (event) => {
            state.values[event.target.name] = event.target.value;
            state.errors = validate(state.values);
            render();
          });
        });

        document.getElementById("support-form").addEventListener("submit", (event) => {
          event.preventDefault();
          state.errors = validate(state.values);
          state.submitted = Object.keys(state.errors).length === 0;
          render();

          const firstInvalid = document.querySelector('[aria-invalid="true"]');
          if (firstInvalid) {
            firstInvalid.focus();
          }
        });
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        bindEvents();
      }

      render();
    </script>
  </body>
</html>
